CREATE TABLE public.parity2_backup(object_kind text NOT NULL,object_name text NOT NULL,original_definition text NOT NULL,backed_up_at timestamptz NOT NULL DEFAULT now(),created_by uuid DEFAULT auth.uid(),updated_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(object_kind,object_name));
GRANT SELECT ON public.parity2_backup TO authenticated;
GRANT ALL ON public.parity2_backup TO service_role;
ALTER TABLE public.parity2_backup ENABLE ROW LEVEL SECURITY;
CREATE POLICY parity2_backup_read ON public.parity2_backup FOR SELECT TO authenticated USING(public.is_tier1_or_super(auth.uid()));
CREATE OR REPLACE FUNCTION public.parity2_rollback() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $rollback$ DECLARE r record; BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Only Super Admin can restore legacy parity definitions';END IF;FOR r IN SELECT * FROM public.parity2_backup ORDER BY CASE object_kind WHEN 'function' THEN 0 ELSE 1 END,object_name LOOP EXECUTE r.original_definition;END LOOP;END $rollback$;
REVOKE ALL ON FUNCTION public.parity2_rollback() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.parity2_rollback() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION pg_temp.parity2_transform(input text) RETURNS text LANGUAGE plpgsql AS $transform$
DECLARE output text:=input;found text[];anchor text;replacement text;suffix text;role_key text;
BEGIN
FOR found IN SELECT regexp_matches(output,$rx$((?:\m(?:NOT\s+)?IN\s*\((?:\s*'[^']+'(?:\s*::\s*(?:public\.)?(?:app_role|text))?\s*,?\s*)+\)|\mARRAY\s*\[(?:\s*'[^']+'(?:\s*::\s*(?:public\.)?(?:app_role|text))?\s*,?\s*)+\]))$rx$,'gi') LOOP
anchor:=found[1];IF position('''managing_director''' IN anchor)=0 THEN CONTINUE;END IF;replacement:=anchor;suffix:=coalesce(substring(anchor FROM $rx$'managing_director'(\s*::\s*(?:public\.)?(?:app_role|text))$rx$),'');
FOREACH role_key IN ARRAY ARRAY['finance_director','sales_director','architecture_director'] LOOP IF position(quote_literal(role_key) IN replacement)=0 THEN replacement:=left(replacement,length(replacement)-1)||', '||quote_literal(role_key)||suffix||right(replacement,1);END IF;END LOOP;output:=replace(output,anchor,replacement);END LOOP;
output:=regexp_replace(output,$rx$(?:public\.)?has_role\(\s*((?:auth\.uid\(\)|[\w.]+))\s*,\s*'managing_director'(?:\s*::\s*(?:public\.)?app_role)?\s*\)$rx$,'public.is_tier1_or_super(\1)','gi');
output:=regexp_replace(output,$rx$(?:public\.)?get_user_role\(\s*((?:auth\.uid\(\)|[\w.]+))\s*\)(?:\s*::\s*(?:text|(?:public\.)?app_role))?\s*=\s*'managing_director'(?:\s*::\s*(?:public\.)?(?:app_role|text))?$rx$,'public.is_tier1_or_super(\1)','gi');
output:=regexp_replace(output,$rx$((?:[\w]+\.)?(?:role|_role|v_role|user_role))(?:\s*::\s*(?:text|(?:public\.)?app_role))?\s*=\s*'managing_director'(?:\s*::\s*(?:public\.)?(?:app_role|text))?$rx$,$replace$\1 IN ('managing_director','finance_director','sales_director','architecture_director')$replace$,'gi');RETURN output;END $transform$;
DO $parity$
DECLARE item jsonb;k text;n text;d text;new_d text;restore_d text;target text;pol record;f_oid oid;changed_count integer:=0;jobs_before text;events_before bigint;flag_before boolean;
BEGIN
SELECT md5(coalesce(jsonb_agg(to_jsonb(j) ORDER BY jobid)::text,'')) INTO jobs_before FROM cron.job j;
SELECT count(*) INTO events_before FROM public.reminder_events;SELECT enabled INTO flag_before FROM public.feature_flags WHERE key='reminders';IF events_before<>0 OR flag_before IS DISTINCT FROM false THEN RAISE EXCEPTION 'Expected reminders OFF and zero events';END IF;
CREATE TEMP TABLE parity2_excluded ON COMMIT DROP AS SELECT 'function' kind,pr.oid::regprocedure::text name,pg_get_functiondef(pr.oid) definition FROM pg_proc pr WHERE pr.pronamespace='public'::regnamespace AND pr.prokind='f' AND (pr.proname||pg_get_functiondef(pr.oid)) ~* 'salary|payroll|compensation|bank|wip|salary_review' UNION ALL SELECT 'policy',schemaname||'.'||tablename||'.'||policyname,coalesce(qual,'')||' '||coalesce(with_check,'') FROM pg_policies WHERE schemaname IN ('public','storage') AND (tablename||policyname||coalesce(qual,'')||coalesce(with_check,'')) ~* 'salary|payroll|compensation|bank|wip|salary_review';
FOR item IN SELECT jsonb_build_array('function','public.'||pr.oid::regprocedure::text) FROM pg_proc pr WHERE pr.pronamespace='public'::regnamespace AND pr.prokind='f' AND pr.proname NOT IN ('is_tier1','reminder_recipient_ids','parity2_rollback') AND pg_get_functiondef(pr.oid) LIKE '%managing_director%' AND (pr.proname||pg_get_functiondef(pr.oid)) !~* 'salary|payroll|compensation|bank|wip|salary_review' AND pg_temp.parity2_transform(pg_get_functiondef(pr.oid))<>pg_get_functiondef(pr.oid) UNION ALL SELECT jsonb_build_array('policy',schemaname||'.'||tablename||'.'||policyname) FROM pg_policies WHERE schemaname IN ('public','storage') AND (tablename||policyname||coalesce(qual,'')||coalesce(with_check,'')) !~* 'salary|payroll|compensation|bank|wip|salary_review' AND pg_temp.parity2_transform(coalesce(qual,'')||' '||coalesce(with_check,''))<>(coalesce(qual,'')||' '||coalesce(with_check,'')) LOOP
k:=item->>0;n:=item->>1;
IF k='function' THEN f_oid:=to_regprocedure(n);IF f_oid IS NULL THEN RAISE EXCEPTION 'Function not found: %',n;END IF;d:=pg_get_functiondef(f_oid);restore_d:=d;
ELSE SELECT * INTO pol FROM pg_policies WHERE schemaname||'.'||tablename||'.'||policyname=n;IF NOT FOUND THEN RAISE EXCEPTION 'Policy not found: %',n;END IF;target:=format('%I.%I',pol.schemaname,pol.tablename);d:=coalesce(pol.qual,'')||' '||coalesce(pol.with_check,'');restore_d:=format('ALTER POLICY %I ON %s',pol.policyname,target);IF pol.qual IS NOT NULL THEN restore_d:=restore_d||' USING ('||pol.qual||')';END IF;IF pol.with_check IS NOT NULL THEN restore_d:=restore_d||' WITH CHECK ('||pol.with_check||')';END IF;END IF;
IF (n||d) ~* 'salary|payroll|compensation|bank|wip|salary_review' THEN RAISE EXCEPTION 'Sensitive object selected: %',n;END IF;
INSERT INTO public.parity2_backup(object_kind,object_name,original_definition) VALUES(k,n,restore_d);new_d:=pg_temp.parity2_transform(d);
IF k='function' AND position('notifications' IN new_d)>0 THEN new_d:=regexp_replace(new_d,'\mSELECT[[:space:]]+(ur\.user_id|p\.auth_user_id)([[:space:]]*,)','SELECT DISTINCT \1\2','gi');new_d:=regexp_replace(new_d,'\mSELECT[[:space:]]+auth_user_id([[:space:]]+FROM[[:space:]]+public\.profiles)','SELECT DISTINCT auth_user_id\1','gi');END IF;
IF new_d=d THEN RAISE EXCEPTION 'Anchor not found: %',n;END IF;
IF k='function' THEN EXECUTE new_d;new_d:=pg_get_functiondef(f_oid);
ELSE new_d:=format('ALTER POLICY %I ON %s',pol.policyname,target);IF pol.qual IS NOT NULL THEN new_d:=new_d||' USING ('||pg_temp.parity2_transform(pol.qual)||')';END IF;IF pol.with_check IS NOT NULL THEN new_d:=new_d||' WITH CHECK ('||pg_temp.parity2_transform(pol.with_check)||')';END IF;EXECUTE new_d;SELECT coalesce(qual,'')||' '||coalesce(with_check,'') INTO new_d FROM pg_policies WHERE schemaname||'.'||tablename||'.'||policyname=n;END IF;
IF position('is_tier1_or_super' IN new_d)=0 AND NOT(new_d LIKE '%managing_director%' AND new_d LIKE '%finance_director%' AND new_d LIKE '%sales_director%' AND new_d LIKE '%architecture_director%') THEN RAISE EXCEPTION 'Parity verification failed: %',n;END IF;changed_count:=changed_count+1;END LOOP;
IF changed_count<>319 OR (SELECT count(*) FROM public.parity2_backup)<>changed_count THEN RAISE EXCEPTION 'Backup/count mismatch: changed %',changed_count;END IF;
IF EXISTS(SELECT 1 FROM parity2_excluded e WHERE e.definition IS DISTINCT FROM CASE WHEN e.kind='function' THEN pg_get_functiondef(to_regprocedure(e.name)) ELSE (SELECT coalesce(qual,'')||' '||coalesce(with_check,'') FROM pg_policies WHERE schemaname||'.'||tablename||'.'||policyname=e.name) END) THEN RAISE EXCEPTION 'Sensitive definition changed';END IF;
IF jobs_before IS DISTINCT FROM (SELECT md5(coalesce(jsonb_agg(to_jsonb(j) ORDER BY jobid)::text,'')) FROM cron.job j) OR (SELECT count(*) FROM public.reminder_events)<>events_before OR (SELECT enabled FROM public.feature_flags WHERE key='reminders') IS DISTINCT FROM flag_before THEN RAISE EXCEPTION 'Reminder/cron invariant violated';END IF;
RAISE NOTICE 'Changed A: %, covered B: 213, pending C: 7, pending D: 0, backup rows: %',changed_count,(SELECT count(*) FROM public.parity2_backup);END $parity$;
UPDATE public.escalation_levels SET after_hours=48 WHERE rule_key IN ('daily_site_report','labour_attendance') AND level=3;